INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6126765, 902121, 115307, '<td valign="top">I don''t quite understand what is Overwhelming about this picture. But since this is also a minimal editing challenge (and my own entries title was quite a stretch) I am voting on image quality mainly. And this is a fantastic image for minimal editing! Very nice, with beautiful colors, good composition, white balance etc. 7</td>', 'I don''t quite understand what is Overwhelming about this picture. But since this is also a minimal editing challenge (and my own entries title was quite a stretch) I am voting on image quality mainly. And this is a fantastic image for minimal editing! Very nice, with beautiful colors, good composition, white balance etc. 7', '2010-08-11 01:11:27.000000', NULL, 1),
(6126781, 901643, 88235, '<td valign="top">cool concept!</td>', 'cool concept!', '2010-08-11 01:17:14.000000', NULL, 1),
