(6126829, 901739, 88235, '<td valign="top">you may want to try a polorizing filter. It would have accentuated your blues.</td>', 'you may want to try a polorizing filter. It would have accentuated your blues.', '2010-08-11 01:37:27.000000', NULL, 1),
(6126881, 902602, 83313, '<td valign="top">Thanks, now I want a soft pretzel at midnight! #!@$!#!!</td>', 'Thanks, now I want a soft pretzel at midnight! #!@$!#!!', '2010-08-11 02:13:48.000000', NULL, 1),
(6126883, 902872, 83313, '<td valign="top">I think that the harsh shadows and lighting are a problem for this. If you were using an on-camera flash, then that was the cause.</td>', 'I think that the harsh shadows and lighting are a problem for this. If you were using an on-camera flash, then that was the cause.', '2010-08-11 02:15:25.000000', NULL, 1),
