(6127479, 902884, 10985, '<td valign="top">Good idea. I would have asked someone to add weight behind me. <br/> <br/>I can see your reflection in the glass. :o)</td>', 'Good idea. I would have asked someone to add weight behind me.  I can see your reflection in the glass. :o)', '2010-08-11 13:41:42.000000', NULL, 1),
(6127487, 902588, 10985, '<td valign="top">Wow, what a scene. One could think it is from a movie where the end of the world is happening and people call to God in despair (from their hands reaching up and their desperate looks).<br/> <br/>A fascinating view and a great pov.</td>', 'Wow, what a scene. One could think it is from a movie where the end of the world is happening and people call to God in despair (from their hands reaching up and their desperate looks). A fascinating view and a great pov.', '2010-08-11 13:43:54.000000', NULL, 1),
(6127488, 902909, 10985, '<td valign="top">Beautiful! Like an ornate necklace. :o)</td>', 'Beautiful! Like an ornate necklace. :o)', '2010-08-11 13:44:30.000000', NULL, 1),
(6127495, 902468, 10985, '<td valign="top">Charming!</td>', 'Charming!', '2010-08-11 13:45:30.000000', NULL, 1),
