(6127505, 902196, 10985, '<td valign="top">Colorful!</td>', 'Colorful!', '2010-08-11 13:51:44.000000', NULL, 1),
(6127510, 902877, 10985, '<td valign="top">Sweet. I love the color and the choice of framing/composition. I really wish both shoes would be as sharp as the one on the right.</td>', 'Sweet. I love the color and the choice of framing/composition. I really wish both shoes would be as sharp as the one on the right.', '2010-08-11 13:52:58.000000', NULL, 1),
(6127512, 902646, 10985, '<td valign="top">Gorgeous color and light. I like the added detail of the droplets, too. Another of my faves for this challenge!</td>', 'Gorgeous color and light. I like the added detail of the droplets, too. Another of my faves for this challenge!', '2010-08-11 13:54:21.000000', NULL, 1),
