(6127516, 902199, 10985, '<td valign="top">Beautiful crisp detail in the man, gorgeous color in the sunset.<br/> <br/>The horizon is tilted.</td>', 'Beautiful crisp detail in the man, gorgeous color in the sunset. The horizon is tilted.', '2010-08-11 13:57:42.000000', NULL, 1),
(6127519, 902482, 10985, '<td valign="top">Cool! I wish one eye was more clearly seen.</td>', 'Cool! I wish one eye was more clearly seen.', '2010-08-11 13:59:25.000000', NULL, 1),
