(6274932, 902218, 96751, '<td valign="top">Perfect capture.  Not understanding the DQ, if you used in-camera shearpening.</td>', 'Perfect capture.  Not understanding the DQ, if you used in-camera shearpening.', '2011-01-07 13:15:07.000000', NULL, 0),
(6275040, 902218, 54446, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tanguera:</b></div><hr/><i> Perfect capture.  Not understanding the DQ, if you used in-camera shearpening. </i></td></tr></table> <br/>My error was using the default sharpening brick in Aperture.  Because that tool allows slider adjustments, it was deemed to be illegal.  The image didn''t need to be sharpened at all.  It was my mistake to use a sharpening tool which could be adjusted.</td>', 'Originally posted by tanguera: Perfect capture.  Not understanding the DQ, if you used in-camera shearpening.  My error was using the default sharpening brick in Aperture.  Because that tool allows slider adjustments, it was deemed to be illegal.  The image didn''t need to be sharpened at all.  It was my mistake to use a sharpening tool which could be adjusted.', '2011-01-07 14:22:16.000000', NULL, 0),
(6284858, 902468, 86447, '<td valign="top">I just love that catchlights in her eyes... and minimal editing!   Wonderful, Ben!</td>', 'I just love that catchlights in her eyes... and minimal editing!   Wonderful, Ben!', '2011-01-16 18:03:02.000000', NULL, 0),
